from mcp.server.auth.provider import AccessToken, TokenVerifier
from mcp.server.auth.middleware.auth_context import get_access_token

class StaticTokenVerifier(TokenVerifier):
    def __init__(self, table: dict[str, list[str]]):
        self.table = table
    async def verify_token(self, token: str) -> AccessToken | None:
        scopes = self.table.get(token)
        return AccessToken(token=token, client_id="static", scopes=scopes) if scopes else None

def current_scopes() -> list[str]:
    tok = get_access_token()                      # None outside an HTTP request
    if tok is not None:
        return list(tok.scopes)
    return [s.strip() for s in os.environ.get("MCP_LOCAL_SCOPES", "donors:read").split(",") if s.strip()]

